// ─── ORDER NOTIFICATION SOUND ─────────────────────────────────────────────────
// Treasure.mp3 is embedded as base64 — zero path/bundler issues, works on all platforms.
// Web: decoded via AudioContext with GainNode (3×) for maximum loudness.
// No external packages needed — uses Web AudioContext API only.
const _TREASURE_B64 =
  "";

const playOrderSound = async () => {
  try {
    // Works on all platforms via AudioContext (web) — no extra packages needed.
    // Decodes the embedded Cute_Ringtone.mp3 base64 and plays it TWICE at max volume.
    const AudioCtx =
      typeof window !== "undefined"
        ? window.AudioContext || window.webkitAudioContext
        : null;
    if (!AudioCtx) return;
    const binaryStr = atob(_TREASURE_B64);
    const bytes = new Uint8Array(binaryStr.length);
    for (let i = 0; i < binaryStr.length; i++)
      bytes[i] = binaryStr.charCodeAt(i);
    const ctx = new AudioCtx();
    // Max loudness chain: source → gain(10×) → compressor → destination
    const gainNode = ctx.createGain();
    gainNode.gain.value = 10.0; // 10× amplification for maximum loudness
    const compressor = ctx.createDynamicsCompressor();
    compressor.threshold.value = -6;
    compressor.knee.value = 0;
    compressor.ratio.value = 20;
    compressor.attack.value = 0;
    compressor.release.value = 0.1;
    gainNode.connect(compressor);
    compressor.connect(ctx.destination);
    const audioBuffer = await ctx.decodeAudioData(bytes.buffer);
    // Play 1st time
    const source1 = ctx.createBufferSource();
    source1.buffer = audioBuffer;
    source1.connect(gainNode);
    source1.start(0);
    // Play 2nd time — starts right after the 1st playback ends
    const source2 = ctx.createBufferSource();
    source2.buffer = audioBuffer;
    source2.connect(gainNode);
    source2.start(audioBuffer.duration);
  } catch (e) {
    /* silent fail — never crash on notification sound */
  }
};

