// ─── WebScrollView ────────────────────────────────────────────────────────────
const WebScrollView = ({
  children,
  style,
  contentContainerStyle,
  horizontal,
  ...rest
}) => {
  if (Platform.OS !== "web") {
    return (
      <ScrollView
        style={style}
        contentContainerStyle={contentContainerStyle}
        horizontal={horizontal}
        showsVerticalScrollIndicator
        {...rest}
      >
        {children}
      </ScrollView>
    );
  }
  const flatContent = StyleSheet.flatten(contentContainerStyle) || {};
  const flatStyle = StyleSheet.flatten(style) || {};
  return (
    <View
      style={[
        { flex: 1, minHeight: 0, position: "relative", overflow: "hidden" },
        flatStyle,
      ]}
    >
      <div
        className="merch-scroll"
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          overflowY: horizontal ? "hidden" : "auto",
          overflowX: horizontal ? "auto" : "hidden",
          display: "flex",
          flexDirection: horizontal ? "row" : "column",
        }}
      >
        <div
          style={{
            display: "flex",
            flexDirection: horizontal ? "row" : "column",
            flexShrink: 0,
            width: "100%",
            gap: flatContent.gap ? flatContent.gap + "px" : undefined,
            paddingTop:
              flatContent.paddingTop !== undefined
                ? flatContent.paddingTop + "px"
                : flatContent.padding !== undefined
                  ? flatContent.padding + "px"
                  : undefined,
            paddingBottom:
              flatContent.paddingBottom !== undefined
                ? flatContent.paddingBottom + "px"
                : flatContent.padding !== undefined
                  ? flatContent.padding + "px"
                  : "12px",
            paddingLeft:
              flatContent.paddingHorizontal !== undefined
                ? flatContent.paddingHorizontal + "px"
                : flatContent.paddingLeft !== undefined
                  ? flatContent.paddingLeft + "px"
                  : flatContent.padding !== undefined
                    ? flatContent.padding + "px"
                    : undefined,
            paddingRight:
              flatContent.paddingHorizontal !== undefined
                ? flatContent.paddingHorizontal + "px"
                : flatContent.paddingRight !== undefined
                  ? flatContent.paddingRight + "px"
                  : flatContent.padding !== undefined
                    ? flatContent.padding + "px"
                    : undefined,
            minWidth: horizontal ? "max-content" : undefined,
            boxSizing: "border-box",
          }}
        >
          {children}
        </div>
      </div>
    </View>
  );
};

// ─── IMAGE RESIZE HELPER ──────────────────────────────────────────────────────
// Resizes any image to max 300×300 and compresses to JPEG 0.5 using canvas.
// Output is a base64 data-URL small enough to fit in a Firestore document (<50KB).
// Works on both web and React Native Web (Expo web build).
const resizeImageToBase64 = (uri) =>
  new Promise((resolve, reject) => {
    const MAX = 300;
    if (Platform.OS === "web") {
      const img = new window.Image();
      img.crossOrigin = "anonymous";
      img.onload = () => {
        const scale = Math.min(MAX / img.width, MAX / img.height, 1);
        const w = Math.round(img.width * scale);
        const h = Math.round(img.height * scale);
        const canvas = document.createElement("canvas");
        canvas.width = w;
        canvas.height = h;
        canvas.getContext("2d").drawImage(img, 0, 0, w, h);
        resolve(canvas.toDataURL("image/jpeg", 0.5));
      };
      img.onerror = reject;
      img.src = uri;
    } else {
      resolve(uri);
    }
  });

