// ─── CASHIER SIZE PICKER MODAL ────────────────────────────────────────────────
const CashierSizePickerModal = ({ visible, item, onConfirm, onClose }) => {
  const [sel, setSel] = useState(null);
  useEffect(() => {
    if (visible) setSel(null);
  }, [visible]);
  if (!item) return null;

  const availSizes = Array.isArray(item.sizes) ? item.sizes : [];
  const adultSizes = availSizes.filter((s) => ADULT_SIZES.includes(s));
  const kidsSizes = availSizes.filter((s) => KIDS_SIZES.includes(s));
  const otherSizes = availSizes.filter(
    (s) => !ADULT_SIZES.includes(s) && !KIDS_SIZES.includes(s),
  );

  const Chip = ({ size, isKids }) => (
    <TouchableOpacity
      onPress={() => setSel(size)}
      style={{
        paddingHorizontal: 14,
        paddingVertical: 9,
        borderRadius: 9,
        backgroundColor:
          sel === size
            ? isKids
              ? "#1a6b45"
              : "#1a3a6b"
            : "rgba(1,31,75,0.07)",
        borderWidth: 1.5,
        borderColor:
          sel === size
            ? isKids
              ? "#1a6b45"
              : "#1a3a6b"
            : "rgba(1,31,75,0.15)",
        minWidth: 46,
        alignItems: "center",
      }}
    >
      <Text
        style={{
          fontFamily: "GoogleSans_700Bold",
          fontSize: 13,
          color: sel === size ? "#fff" : "rgba(1,31,75,0.65)",
        }}
      >
        {size}
      </Text>
    </TouchableOpacity>
  );

  return (
    <Modal
      visible={visible}
      transparent
      animationType="fade"
      onRequestClose={onClose}
    >
      <View
        style={{
          flex: 1,
          backgroundColor: "rgba(1,20,50,0.60)",
          justifyContent: "center",
          alignItems: "center",
          padding: 24,
        }}
      >
        <TouchableOpacity
          style={StyleSheet.absoluteFillObject}
          onPress={onClose}
          activeOpacity={1}
        />
        <View
          style={{
            backgroundColor: "#fff",
            borderRadius: 18,
            padding: 22,
            width: 340,
            gap: 14,
          }}
        >
          {/* Header */}
          <View style={{ alignItems: "center", gap: 4 }}>
            <Text
              style={{
                fontFamily: "GoogleSans_700Bold",
                fontSize: 15,
                color: "#1a3a6b",
              }}
            >
              {item.emoji} Select Size
            </Text>
            <Text
              style={{
                fontFamily: "GoogleSans_400Regular",
                fontSize: 12,
                color: "rgba(1,31,75,0.55)",
                textAlign: "center",
              }}
              numberOfLines={2}
            >
              {item.name}
            </Text>
          </View>

          {availSizes.length === 0 ? (
            <Text
              style={{
                fontFamily: "GoogleSans_400Regular",
                fontSize: 12,
                color: "rgba(1,31,75,0.45)",
                textAlign: "center",
                paddingVertical: 8,
              }}
            >
              No sizes configured for this item.
            </Text>
          ) : (
            <View style={{ gap: 10 }}>
              {adultSizes.length > 0 && (
                <View style={{ gap: 6 }}>
                  <Text
                    style={{
                      fontFamily: "GoogleSans_700Bold",
                      fontSize: 9,
                      color: "rgba(26,58,107,0.50)",
                      letterSpacing: 1.2,
                      textTransform: "uppercase",
                    }}
                  >
                    ADULT
                  </Text>
                  <View
                    style={{ flexDirection: "row", flexWrap: "wrap", gap: 6 }}
                  >
                    {adultSizes.map((sz) => (
                      <Chip key={sz} size={sz} isKids={false} />
                    ))}
                  </View>
                </View>
              )}
              {kidsSizes.length > 0 && (
                <View style={{ gap: 6 }}>
                  <Text
                    style={{
                      fontFamily: "GoogleSans_700Bold",
                      fontSize: 9,
                      color: "rgba(26,107,69,0.60)",
                      letterSpacing: 1.2,
                      textTransform: "uppercase",
                    }}
                  >
                    KIDS
                  </Text>
                  <View
                    style={{ flexDirection: "row", flexWrap: "wrap", gap: 6 }}
                  >
                    {kidsSizes.map((sz) => (
                      <Chip key={sz} size={sz} isKids={true} />
                    ))}
                  </View>
                </View>
              )}
              {otherSizes.length > 0 && (
                <View style={{ gap: 6 }}>
                  <Text
                    style={{
                      fontFamily: "GoogleSans_700Bold",
                      fontSize: 9,
                      color: "rgba(1,31,75,0.45)",
                      letterSpacing: 1.2,
                      textTransform: "uppercase",
                    }}
                  >
                    OTHER
                  </Text>
                  <View
                    style={{ flexDirection: "row", flexWrap: "wrap", gap: 6 }}
                  >
                    {otherSizes.map((sz) => (
                      <Chip key={sz} size={sz} isKids={false} />
                    ))}
                  </View>
                </View>
              )}
            </View>
          )}

          {/* Buttons */}
          <View style={{ flexDirection: "row", gap: 8, marginTop: 2 }}>
            <TouchableOpacity
              onPress={onClose}
              style={{
                flex: 1,
                paddingVertical: 11,
                borderRadius: 10,
                backgroundColor: "rgba(1,31,75,0.07)",
                alignItems: "center",
              }}
            >
              <Text
                style={{
                  fontFamily: "GoogleSans_700Bold",
                  fontSize: 13,
                  color: "rgba(1,31,75,0.50)",
                }}
              >
                Cancel
              </Text>
            </TouchableOpacity>
            <TouchableOpacity
              onPress={() => {
                if (sel) onConfirm(sel);
              }}
              style={{
                flex: 2,
                paddingVertical: 11,
                borderRadius: 10,
                backgroundColor: sel ? "#1a3a6b" : "rgba(1,31,75,0.20)",
                alignItems: "center",
              }}
            >
              <Text
                style={{
                  fontFamily: "GoogleSans_700Bold",
                  fontSize: 13,
                  color: "#fff",
                }}
              >
                {sel ? `Add to Cart — ${sel}` : "Pick a size first"}
              </Text>
            </TouchableOpacity>
          </View>
        </View>
      </View>
    </Modal>
  );
};

// ─── PAYMENT CONFIRMATION MODAL ───────────────────────────────────────────────
const PaymentConfirmModal = ({
  visible,
  paymentMode,
  total,
  cartItems,
  memberName,
  memberId,
  onConfirm,
  onCancel,
}) => {
  const [amountPaid, setAmountPaid] = useState("");
  const [gcashRef, setGcashRef] = useState("");
  const [gcashConfirmed, setGcashConfirmed] = useState(false);
  const [placing, setPlacing] = useState(false);

  useEffect(() => {
    if (visible) {
      setAmountPaid("");
      setGcashRef("");
      setGcashConfirmed(false);
      setPlacing(false);
    }
  }, [visible, paymentMode]);

  const paid = parseFloat(amountPaid) || 0;
  const change = paid - total;

  const canConfirm = () => {
    if (!cartItems || cartItems.length === 0) return false;
    if (paymentMode === "cash") return paid >= total;
    if (paymentMode === "gcash")
      return gcashRef.trim().length >= 4 && gcashConfirmed;
    if (paymentMode === "credit") return (memberName || "").trim().length > 0;
    return false;
  };

  const handleConfirm = async () => {
    if (!canConfirm() || placing) return;
    setPlacing(true);
    await onConfirm({
      payment: paymentMode,
      amountPaid: paymentMode === "cash" ? paid : total,
      change: paymentMode === "cash" ? change : 0,
      gcashRef: paymentMode === "gcash" ? gcashRef.trim() : null,
      memberName: paymentMode === "credit" ? memberName : null,
      memberId: paymentMode === "credit" ? memberId : null,
      settled: paymentMode !== "credit",
    });
    setPlacing(false);
  };

  if (!visible) return null;

  return (
    <Modal visible transparent animationType="fade" onRequestClose={onCancel}>
      <View style={pcm.overlay}>
        <TouchableOpacity
          style={StyleSheet.absoluteFillObject}
          onPress={onCancel}
          activeOpacity={1}
        />
        <View style={pcm.card}>
          <LinearGradient colors={["#1a2d4e", "#243554"]} style={pcm.header}>
            <Text style={pcm.headerTitle}>
              {paymentMode === "cash"
                ? "💵 Cash Payment"
                : paymentMode === "gcash"
                  ? "📱 GCash Payment"
                  : "🪙 Credit / Utang"}
            </Text>
            <Text style={pcm.headerSub}>Total: ₱{total.toFixed(2)}</Text>
          </LinearGradient>

          <View style={pcm.body}>
            {paymentMode === "cash" && (
              <>
                <Text style={pcm.label}>Amount Received from Customer</Text>
                <TextInput
                  style={pcm.input}
                  value={amountPaid}
                  onChangeText={setAmountPaid}
                  keyboardType="numeric"
                  placeholder="₱ 0.00"
                  placeholderTextColor="rgba(1,31,75,0.30)"
                  autoFocus
                />
                {amountPaid !== "" && (
                  <View
                    style={[
                      pcm.changeBox,
                      {
                        backgroundColor:
                          change < 0
                            ? "rgba(231,76,60,0.10)"
                            : "rgba(39,174,96,0.10)",
                        borderColor:
                          change < 0
                            ? "rgba(231,76,60,0.25)"
                            : "rgba(39,174,96,0.25)",
                      },
                    ]}
                  >
                    <Text style={pcm.changeLbl}>
                      {change < 0 ? "⚠️ Kulang pa:" : "Change:"}
                    </Text>
                    <Text
                      style={[
                        pcm.changeVal,
                        { color: change < 0 ? "#e74c3c" : "#27ae60" },
                      ]}
                    >
                      ₱{Math.abs(change).toFixed(2)}
                    </Text>
                  </View>
                )}
                {paid < total && amountPaid !== "" && (
                  <Text style={pcm.errorTxt}>
                    Hindi pa pwede mag-place ng order — kulang ang bayad.
                  </Text>
                )}
              </>
            )}

            {paymentMode === "gcash" && (
              <>
                <Text style={pcm.label}>GCash Reference Number</Text>
                <TextInput
                  style={pcm.input}
                  value={gcashRef}
                  onChangeText={setGcashRef}
                  placeholder="e.g. 1234567890"
                  placeholderTextColor="rgba(1,31,75,0.30)"
                  keyboardType="numeric"
                  maxLength={20}
                  autoFocus
                />
                <Text style={pcm.hint}>
                  Itype ang reference number gikan sa GCash receipt/notification
                  sa customer.
                </Text>
                <TouchableOpacity
                  style={[pcm.checkRow, gcashConfirmed && pcm.checkRowActive]}
                  onPress={() => setGcashConfirmed((v) => !v)}
                  activeOpacity={0.8}
                >
                  <View
                    style={[pcm.checkbox, gcashConfirmed && pcm.checkboxActive]}
                  >
                    {gcashConfirmed && (
                      <Text
                        style={{ color: "#fff", fontSize: 12, lineHeight: 16 }}
                      >
                        ✓
                      </Text>
                    )}
                  </View>
                  <Text
                    style={[
                      pcm.checkLabel,
                      gcashConfirmed && { color: "#1a3a6b" },
                    ]}
                  >
                    Na-verify na nako ang GCash payment sa phone — ₱
                    {total.toFixed(2)} na-receive.
                  </Text>
                </TouchableOpacity>
                {gcashRef.trim().length > 0 && gcashRef.trim().length < 4 && (
                  <Text style={pcm.errorTxt}>
                    Reference number too short — minimum 4 digits.
                  </Text>
                )}
                {gcashRef.trim().length >= 4 && !gcashConfirmed && (
                  <Text style={pcm.warnTxt}>
                    ⚠️ I-check ang GCash app ug i-tick ang confirmation box.
                  </Text>
                )}
              </>
            )}

            {paymentMode === "credit" && (
              <>
                <View style={pcm.creditBanner}>
                  <Text style={pcm.creditBannerIco}>🪙</Text>
                  <View style={{ flex: 1 }}>
                    <Text style={pcm.creditBannerName}>
                      {memberName || "Unknown Member"}
                    </Text>
                    {memberId ? (
                      <Text style={pcm.creditBannerId}>ID: {memberId}</Text>
                    ) : null}
                  </View>
                  <Text style={pcm.creditBannerAmt}>+₱{total.toFixed(2)}</Text>
                </View>
                <Text style={pcm.hint}>
                  Ang order ibutang sa credit/utang ni {memberName || "member"}.
                  Dili kini bayad karon — makita sa Credits tab para sa
                  settlement.
                </Text>
                {!(memberName || "").trim() && (
                  <Text style={pcm.errorTxt}>
                    Walay napili nga member — dili pwede mag-proceed.
                  </Text>
                )}
              </>
            )}
          </View>

          <View style={pcm.actions}>
            <TouchableOpacity style={pcm.cancelBtn} onPress={onCancel}>
              <Text style={pcm.cancelTxt}>Cancel</Text>
            </TouchableOpacity>
            <TouchableOpacity
              style={[
                pcm.confirmBtn,
                (!canConfirm() || placing) && { opacity: 0.45 },
              ]}
              onPress={handleConfirm}
              activeOpacity={0.8}
              disabled={!canConfirm() || placing}
            >
              <LinearGradient
                colors={
                  canConfirm() && !placing
                    ? ["#27ae60", "#2ecc71"]
                    : ["#aaa", "#bbb"]
                }
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 0 }}
                style={pcm.confirmGrad}
              >
                <MaterialIcons name="check-circle" size={16} color="#fff" />
                <Text style={pcm.confirmTxt}>
                  {placing
                    ? "Saving..."
                    : paymentMode === "credit"
                      ? "Confirm Credit"
                      : "Confirm Payment"}
                </Text>
              </LinearGradient>
            </TouchableOpacity>
          </View>
        </View>
      </View>
    </Modal>
  );
};

