// ─── CASHIER SCREEN ───────────────────────────────────────────────────────────
const CashierScreen = ({
  items,
  categories,
  addOrder,
  deductStock,
  isWide,
}) => {
  const [activeCat, setActiveCat] = useState("All");
  const [search, setSearch] = useState("");
  const [cart, setCart] = useState({});
  const [paymentMode, setPaymentMode] = useState("cash");
  const [memberName, setMemberName] = useState("");
  const [memberId, setMemberId] = useState("");
  const [payModalVisible, setPayModalVisible] = useState(false);
  const [receiptVisible, setReceiptVisible] = useState(false);
  const [lastOrder, setLastOrder] = useState(null);
  const [sizePickerItem, setSizePickerItem] = useState(null);
  const [cartCollapsed, setCartCollapsed] = useState(true);
  const slideAnim = useRef(new Animated.Value(0)).current;
  const openCart = () => {
    setCartCollapsed(false);
    Animated.spring(slideAnim, {
      toValue: 1,
      tension: 65,
      friction: 11,
      useNativeDriver: true,
    }).start();
  };
  const closeCart = () => {
    Animated.timing(slideAnim, {
      toValue: 0,
      duration: 200,
      useNativeDriver: true,
    }).start(() => setCartCollapsed(true));
  };

  const needsSize = (item) =>
    Array.isArray(item.sizes) && item.sizes.length > 0;

  const filtered = items.filter((i) => {
    if (search.trim())
      return i.name.toLowerCase().includes(search.toLowerCase());
    return activeCat === "All" || i.cat === activeCat;
  });

  const cartItems = Object.values(cart).filter((c) => c.qty > 0);
  const total = cartItems.reduce((s, { item, qty }) => s + item.price * qty, 0);

  const cartKey = (item, size) => (size ? `${item.id}-${size}` : item.id);

  const addToCart = (item, size) => {
    if (needsSize(item) && !size) {
      setSizePickerItem(item);
      return;
    }
    const key = cartKey(item, size);
    setCart((prev) => ({
      ...prev,
      [key]: {
        item,
        qty: (prev[key] ? prev[key].qty : 0) + 1,
        size: size || null,
      },
    }));
  };

  const removeFromCart = (item, size) => {
    const key = cartKey(item, size);
    setCart((prev) => {
      const qty = (prev[key] ? prev[key].qty : 0) - 1;
      if (qty <= 0) {
        const n = { ...prev };
        delete n[key];
        return n;
      }
      return { ...prev, [key]: { item, qty, size: size || null } };
    });
  };

  const clearCart = () => {
    setCart({});
    setMemberName("");
    setMemberId("");
  };

  // Only called after PaymentConfirmModal validates — order is guaranteed paid/verified
  const handleConfirmedOrder = async ({
    payment,
    amountPaid,
    change,
    gcashRef,
    memberName: mn,
    memberId: mid,
    settled,
  }) => {
    const orderNo = Math.floor(1000 + Math.random() * 9000);
    const now = new Date();
    const time =
      now.toLocaleDateString("en-PH", {
        month: "short",
        day: "numeric",
        year: "numeric",
      }) +
      "  " +
      now.toLocaleTimeString("en-PH", { hour: "2-digit", minute: "2-digit" });
    const order = {
      id: Date.now().toString(),
      orderNo,
      time,
      items: cartItems,
      total,
      amountPaid,
      change,
      payment,
      gcashRef: gcashRef || null,
      memberName: mn || null,
      memberId: mid || null,
      settled,
      status: "done",
      source: "cashier",
    };
    await addOrder(order);
    await deductStock(cartItems);
    setLastOrder(order);
    setPayModalVisible(false);
    clearCart();
    setTimeout(() => setReceiptVisible(true), 200);
  };

  // Responsive columns
  const COLS = isWide ? 6 : 3;

  return (
    <View
      style={{
        flex: 1,
        flexDirection: isWide ? "row" : "column",
        minHeight: 0,
        overflow: "hidden",
      }}
    >
      {/* Items side */}
      <View
        style={{
          flex: 1,
          minHeight: 0,
          minWidth: 0,
          flexDirection: "column",
          overflow: "hidden",
        }}
      >
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          style={{ flexGrow: 0, marginBottom: 6 }}
          contentContainerStyle={{
            paddingHorizontal: 10,
            gap: 5,
            paddingVertical: 4,
          }}
        >
          {categories.map((cat) => (
            <TouchableOpacity
              key={cat}
              style={[cs.catTab, activeCat === cat && cs.catTabActive]}
              onPress={() => setActiveCat(cat)}
            >
              <Text
                style={[cs.catTabTxt, activeCat === cat && cs.catTabTxtActive]}
              >
                {cat}
              </Text>
            </TouchableOpacity>
          ))}
        </ScrollView>

        <View style={cs.searchRow}>
          <MaterialIcons name="search" size={15} color="rgba(1,31,75,0.40)" />
          <TextInput
            style={cs.searchInput}
            placeholder="Search items..."
            placeholderTextColor="rgba(1,31,75,0.35)"
            value={search}
            onChangeText={setSearch}
          />
          {search.length > 0 && (
            <TouchableOpacity onPress={() => setSearch("")}>
              <Text style={{ color: "rgba(1,31,75,0.40)", fontWeight: "700" }}>
                ✕
              </Text>
            </TouchableOpacity>
          )}
        </View>

        {/* FIX: padding 10/12, gap 8 */}
        <WebScrollView
          style={{ flex: 1 }}
          contentContainerStyle={{
            paddingTop: 10,
            paddingHorizontal: 12,
            paddingBottom: 20,
            gap: 8,
          }}
        >
          {Array.from(
            { length: Math.ceil(filtered.length / COLS) },
            (_, rowIdx) => (
              <View
                key={rowIdx}
                style={{ flexDirection: "row", gap: 8, alignItems: "stretch" }}
              >
                {filtered
                  .slice(rowIdx * COLS, rowIdx * COLS + COLS)
                  .map((item) => (
                    <View
                      key={item.id}
                      style={{ flex: 1, alignSelf: "stretch" }}
                    >
                      <TouchableOpacity
                        style={[
                          cs.itemCard,
                          item.stock === 0 && { opacity: 0.45 },
                          { flex: 1 },
                        ]}
                        onPress={() => item.stock > 0 && addToCart(item, null)}
                        activeOpacity={item.stock > 0 ? 0.75 : 1}
                      >
                        <View style={cs.itemImgCircle}>
                          {item.image ? (
                            <Image
                              source={{ uri: item.image }}
                              style={{
                                width: "100%",
                                height: "100%",
                                borderRadius: 99,
                              }}
                              resizeMode="cover"
                            />
                          ) : (
                            <Text style={cs.itemEmoji}>{item.emoji}</Text>
                          )}
                        </View>
                        <Text style={cs.itemCardName} numberOfLines={2}>
                          {item.name}
                        </Text>
                        <Text style={cs.itemCardPrice}>₱{item.price}</Text>
                        <Text style={cs.itemCardStock}>
                          {item.stock === 0
                            ? "Out of stock"
                            : "Stock: " + item.stock}
                        </Text>
                        {Array.isArray(item.sizes) && item.sizes.length > 0 && (
                          <View
                            style={{
                              backgroundColor: "rgba(26,58,107,0.10)",
                              borderRadius: 4,
                              paddingHorizontal: 5,
                              paddingVertical: 2,
                              marginTop: 1,
                            }}
                          >
                            <Text
                              style={{
                                fontFamily: "GoogleSans_700Bold",
                                fontSize: 7,
                                color: "#1a3a6b",
                              }}
                            >
                              👕 Tap to pick size
                            </Text>
                          </View>
                        )}
                        {(() => {
                          const totalInCart = Object.entries(cart)
                            .filter(
                              ([k]) =>
                                k === item.id || k.startsWith(item.id + "-"),
                            )
                            .reduce((s, [, v]) => s + v.qty, 0);
                          return totalInCart > 0 ? (
                            <View style={cs.cartBadge}>
                              <Text style={cs.cartBadgeTxt}>{totalInCart}</Text>
                            </View>
                          ) : null;
                        })()}
                      </TouchableOpacity>
                    </View>
                  ))}
                {Array.from({
                  length:
                    COLS -
                    filtered.slice(rowIdx * COLS, rowIdx * COLS + COLS).length,
                }).map((_, i) => (
                  <View key={"e-" + i} style={{ flex: 1 }} />
                ))}
              </View>
            ),
          )}
        </WebScrollView>
      </View>

      {/* Wide: side cart panel */}
      {isWide && (
        <View style={cs.cartPanel}>
          <Text style={cs.cartTitle}>
            🛒 CART {cartItems.length > 0 ? `(${cartItems.length})` : ""}
          </Text>
          <View style={cs.cartItemsBox}>
            {cartItems.length === 0 ? (
              <Text style={cs.cartEmpty}>No items added yet</Text>
            ) : (
              <WebScrollView style={{ flex: 1 }}>
                {cartItems.map(({ item, qty, size }) => (
                  <View
                    key={size ? item.id + "-" + size : item.id}
                    style={cs.cartRow}
                  >
                    <Text style={cs.cartEmoji}>{item.emoji}</Text>
                    <View style={{ flex: 1, minWidth: 0 }}>
                      <Text style={cs.cartName} numberOfLines={1}>
                        {item.name}
                        {size ? " [" + size + "]" : ""}
                      </Text>
                      <Text style={cs.cartSub}>
                        ₱{item.price} × {qty} = ₱{item.price * qty}
                      </Text>
                    </View>
                    <View style={cs.qtyRow}>
                      <TouchableOpacity
                        style={cs.qBtn}
                        onPress={() => removeFromCart(item, size)}
                      >
                        <Text style={cs.qBtnTxt}>−</Text>
                      </TouchableOpacity>
                      <Text style={cs.qVal}>{qty}</Text>
                      <TouchableOpacity
                        style={[cs.qBtn, { backgroundColor: "#1a3a6b" }]}
                        onPress={() => addToCart(item, size)}
                      >
                        <Text style={[cs.qBtnTxt, { color: "#fff" }]}>+</Text>
                      </TouchableOpacity>
                    </View>
                  </View>
                ))}
              </WebScrollView>
            )}
          </View>
          <View style={cs.totalRow}>
            <Text style={cs.totalLbl}>TOTAL</Text>
            <Text style={cs.totalVal}>₱ {total.toFixed(2)}</Text>
          </View>

          {/* Payment method tabs */}
          <View style={{ gap: 4 }}>
            <Text
              style={{
                fontFamily: "GoogleSans_700Bold",
                fontSize: 9,
                color: "rgba(1,31,75,0.50)",
                letterSpacing: 1,
                textTransform: "uppercase",
              }}
            >
              Payment Method
            </Text>
            <View style={{ flexDirection: "row", gap: 4 }}>
              {[
                ["cash", "💵", "Cash"],
                ["gcash", "📱", "GCash"],
                ["credit", "🪙", "Credit"],
              ].map(([mode, icon, label]) => (
                <TouchableOpacity
                  key={mode}
                  style={[cs.payChip, paymentMode === mode && cs.payChipActive]}
                  onPress={() => setPaymentMode(mode)}
                  activeOpacity={0.8}
                >
                  <Text style={{ fontSize: 13 }}>{icon}</Text>
                  <Text
                    style={[
                      cs.payChipTxt,
                      paymentMode === mode && cs.payChipTxtActive,
                    ]}
                  >
                    {label}
                  </Text>
                </TouchableOpacity>
              ))}
            </View>
          </View>

          {/* Credit: member name fields */}
          {paymentMode === "credit" && (
            <View style={{ gap: 4 }}>
              <Text
                style={{
                  fontFamily: "GoogleSans_700Bold",
                  fontSize: 9,
                  color: "rgba(1,31,75,0.50)",
                  letterSpacing: 1,
                  textTransform: "uppercase",
                }}
              >
                Member Name *
              </Text>
              <TextInput
                style={cs.amtInput}
                value={memberName}
                onChangeText={setMemberName}
                placeholder="Full name / ID number"
                placeholderTextColor="rgba(1,31,75,0.30)"
              />
              <TextInput
                style={[cs.amtInput, { marginTop: 4 }]}
                value={memberId}
                onChangeText={setMemberId}
                placeholder="Member ID (optional)"
                placeholderTextColor="rgba(1,31,75,0.30)"
              />
            </View>
          )}

          <TouchableOpacity
            style={[
              cs.orderBtn,
              (cartItems.length === 0 ||
                (paymentMode === "credit" && !memberName.trim())) && {
                opacity: 0.45,
              },
            ]}
            onPress={() => {
              if (cartItems.length === 0) return;
              if (paymentMode === "credit" && !memberName.trim()) {
                Alert.alert(
                  "Member Required",
                  "Ibutang ang pangalan sa member para sa credit order.",
                );
                return;
              }
              setPayModalVisible(true);
            }}
            activeOpacity={0.8}
          >
            <LinearGradient
              colors={
                cartItems.length > 0 ? ["#1a3a6b", "#2e5fa3"] : ["#aaa", "#bbb"]
              }
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 0 }}
              style={cs.orderBtnGrad}
            >
              <MaterialIcons
                name={
                  paymentMode === "cash"
                    ? "payments"
                    : paymentMode === "gcash"
                      ? "phone-android"
                      : "account-balance"
                }
                size={16}
                color="#fff"
              />
              <Text style={cs.orderBtnTxt}>
                {paymentMode === "cash"
                  ? "Proceed to Payment"
                  : paymentMode === "gcash"
                    ? "Verify GCash"
                    : "Add to Credit"}
              </Text>
            </LinearGradient>
          </TouchableOpacity>
          <TouchableOpacity style={cs.clearBtn} onPress={clearCart}>
            <MaterialIcons name="delete-sweep" size={14} color="#e74c3c" />
            <Text style={cs.clearBtnTxt}>Clear Cart</Text>
          </TouchableOpacity>
          {lastOrder && (
            <TouchableOpacity
              style={cs.receiptBtn}
              onPress={() => setReceiptVisible(true)}
            >
              <MaterialIcons name="receipt" size={14} color="#1a3a6b" />
              <Text style={cs.receiptBtnTxt}>Last Receipt</Text>
            </TouchableOpacity>
          )}
        </View>
      )}

      {/* Mobile: floating pill + animated bottom sheet (same as CanteenVisitor) */}
      {!isWide && (
        <>
          {/* Floating gold pill */}
          <TouchableOpacity
            style={cs.floatCart}
            onPress={openCart}
            activeOpacity={0.85}
          >
            <LinearGradient
              colors={["#c9a84c", "#e8c87a"]}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 0 }}
              style={cs.floatCartGrad}
            >
              <Text style={cs.floatCartTxt}>
                🛒 View Cart{" "}
                {cartItems.length > 0 ? `(${cartItems.length})` : ""} • ₱
                {total.toFixed(2)}
              </Text>
            </LinearGradient>
          </TouchableOpacity>
          {/* Bottom sheet */}
          {!cartCollapsed && (
            <View style={cs.sheetOverlay}>
              <TouchableOpacity
                style={cs.sheetBackdrop}
                onPress={closeCart}
                activeOpacity={1}
              />
              <Animated.View
                style={[
                  cs.sheet,
                  {
                    transform: [
                      {
                        translateY: slideAnim.interpolate({
                          inputRange: [0, 1],
                          outputRange: [600, 0],
                        }),
                      },
                    ],
                  },
                ]}
              >
                <View style={cs.sheetHandle} />
                <View style={cs.sheetHeader}>
                  <Text style={cs.cartTitle}>
                    🛒 CART{" "}
                    {cartItems.length > 0 ? `(${cartItems.length})` : ""}
                  </Text>
                  <TouchableOpacity onPress={closeCart} style={cs.sheetClose}>
                    <Text style={{ color: "rgba(1,31,75,0.6)", fontSize: 14 }}>
                      ✕
                    </Text>
                  </TouchableOpacity>
                </View>
                <ScrollView
                  showsVerticalScrollIndicator={false}
                  keyboardShouldPersistTaps="handled"
                  contentContainerStyle={{ flexGrow: 1 }}
                >
                  <View style={{ padding: 12, gap: 8 }}>
                    <View style={cs.cartItemsBox}>
                      {cartItems.length === 0 ? (
                        <Text style={cs.cartEmpty}>No items added yet</Text>
                      ) : (
                        <WebScrollView style={{ flex: 1 }}>
                          {cartItems.map(({ item, qty, size }) => (
                            <View
                              key={size ? item.id + "-" + size : item.id}
                              style={cs.cartRow}
                            >
                              <Text style={cs.cartEmoji}>{item.emoji}</Text>
                              <View style={{ flex: 1, minWidth: 0 }}>
                                <Text style={cs.cartName} numberOfLines={1}>
                                  {item.name}
                                  {size ? " [" + size + "]" : ""}
                                </Text>
                                <Text style={cs.cartSub}>
                                  ₱{item.price} × {qty} = ₱{item.price * qty}
                                </Text>
                              </View>
                              <View style={cs.qtyRow}>
                                <TouchableOpacity
                                  style={cs.qBtn}
                                  onPress={() => removeFromCart(item, size)}
                                >
                                  <Text style={cs.qBtnTxt}>−</Text>
                                </TouchableOpacity>
                                <Text style={cs.qVal}>{qty}</Text>
                                <TouchableOpacity
                                  style={[
                                    cs.qBtn,
                                    { backgroundColor: "#1a3a6b" },
                                  ]}
                                  onPress={() => addToCart(item, size)}
                                >
                                  <Text style={[cs.qBtnTxt, { color: "#fff" }]}>
                                    +
                                  </Text>
                                </TouchableOpacity>
                              </View>
                            </View>
                          ))}
                        </WebScrollView>
                      )}
                    </View>
                    <View style={cs.totalRow}>
                      <Text style={cs.totalLbl}>TOTAL</Text>
                      <Text style={cs.totalVal}>₱ {total.toFixed(2)}</Text>
                    </View>

                    {/* Payment method tabs */}
                    <View style={{ gap: 4 }}>
                      <Text
                        style={{
                          fontFamily: "GoogleSans_700Bold",
                          fontSize: 9,
                          color: "rgba(1,31,75,0.50)",
                          letterSpacing: 1,
                          textTransform: "uppercase",
                        }}
                      >
                        Payment Method
                      </Text>
                      <View style={{ flexDirection: "row", gap: 4 }}>
                        {[
                          ["cash", "💵", "Cash"],
                          ["gcash", "📱", "GCash"],
                          ["credit", "🪙", "Credit"],
                        ].map(([mode, icon, label]) => (
                          <TouchableOpacity
                            key={mode}
                            style={[
                              cs.payChip,
                              paymentMode === mode && cs.payChipActive,
                            ]}
                            onPress={() => setPaymentMode(mode)}
                            activeOpacity={0.8}
                          >
                            <Text style={{ fontSize: 13 }}>{icon}</Text>
                            <Text
                              style={[
                                cs.payChipTxt,
                                paymentMode === mode && cs.payChipTxtActive,
                              ]}
                            >
                              {label}
                            </Text>
                          </TouchableOpacity>
                        ))}
                      </View>
                    </View>

                    {paymentMode === "credit" && (
                      <View style={{ gap: 4 }}>
                        <Text
                          style={{
                            fontFamily: "GoogleSans_700Bold",
                            fontSize: 9,
                            color: "rgba(1,31,75,0.50)",
                            letterSpacing: 1,
                            textTransform: "uppercase",
                          }}
                        >
                          Member Name *
                        </Text>
                        <TextInput
                          style={cs.amtInput}
                          value={memberName}
                          onChangeText={setMemberName}
                          placeholder="Full name / ID number"
                          placeholderTextColor="rgba(1,31,75,0.30)"
                        />
                        <TextInput
                          style={[cs.amtInput, { marginTop: 4 }]}
                          value={memberId}
                          onChangeText={setMemberId}
                          placeholder="Member ID (optional)"
                          placeholderTextColor="rgba(1,31,75,0.30)"
                        />
                      </View>
                    )}

                    <TouchableOpacity
                      style={[
                        cs.orderBtn,
                        (cartItems.length === 0 ||
                          (paymentMode === "credit" && !memberName.trim())) && {
                          opacity: 0.45,
                        },
                      ]}
                      onPress={() => {
                        if (cartItems.length === 0) return;
                        if (paymentMode === "credit" && !memberName.trim()) {
                          Alert.alert(
                            "Member Required",
                            "Ibutang ang pangalan sa member para sa credit order.",
                          );
                          return;
                        }
                        setPayModalVisible(true);
                      }}
                      activeOpacity={0.8}
                    >
                      <LinearGradient
                        colors={
                          cartItems.length > 0
                            ? ["#1a3a6b", "#2e5fa3"]
                            : ["#aaa", "#bbb"]
                        }
                        start={{ x: 0, y: 0 }}
                        end={{ x: 1, y: 0 }}
                        style={cs.orderBtnGrad}
                      >
                        <MaterialIcons
                          name={
                            paymentMode === "cash"
                              ? "payments"
                              : paymentMode === "gcash"
                                ? "phone-android"
                                : "account-balance"
                          }
                          size={16}
                          color="#fff"
                        />
                        <Text style={cs.orderBtnTxt}>
                          {paymentMode === "cash"
                            ? "Proceed to Payment"
                            : paymentMode === "gcash"
                              ? "Verify GCash"
                              : "Add to Credit"}
                        </Text>
                      </LinearGradient>
                    </TouchableOpacity>
                    <TouchableOpacity style={cs.clearBtn} onPress={clearCart}>
                      <MaterialIcons
                        name="delete-sweep"
                        size={14}
                        color="#e74c3c"
                      />
                      <Text style={cs.clearBtnTxt}>Clear Cart</Text>
                    </TouchableOpacity>
                  </View>
                </ScrollView>
              </Animated.View>
            </View>
          )}
        </>
      )}

      {/* Payment confirmation modal — gated before order saves */}
      <PaymentConfirmModal
        visible={payModalVisible}
        paymentMode={paymentMode}
        total={total}
        cartItems={cartItems}
        memberName={memberName}
        memberId={memberId}
        onConfirm={handleConfirmedOrder}
        onCancel={() => setPayModalVisible(false)}
      />

      {receiptVisible && lastOrder && (
        <Modal
          transparent
          visible
          animationType="fade"
          onRequestClose={() => setReceiptVisible(false)}
        >
          <View
            style={{
              flex: 1,
              backgroundColor: "rgba(1,20,50,0.65)",
              justifyContent: "center",
              alignItems: "center",
              padding: 20,
            }}
          >
            <TouchableOpacity
              style={StyleSheet.absoluteFillObject}
              onPress={() => setReceiptVisible(false)}
              activeOpacity={1}
            />
            <View style={cs.receipt}>
              <Text style={cs.receiptTitle}>🧾 RECEIPT</Text>
              <Text style={cs.receiptSub}>CESLA Merchandise</Text>
              <View
                style={{
                  height: 1,
                  borderStyle: "dashed",
                  borderTopWidth: 1,
                  borderColor: "rgba(1,31,75,0.20)",
                  marginVertical: 10,
                }}
              />
              <Text style={cs.receiptMeta}>Order #{lastOrder.orderNo}</Text>
              <Text style={cs.receiptMeta}>{lastOrder.time}</Text>
              <View
                style={{
                  height: 1,
                  borderStyle: "dashed",
                  borderTopWidth: 1,
                  borderColor: "rgba(1,31,75,0.20)",
                  marginVertical: 10,
                }}
              />
              <ScrollView
                style={{ maxHeight: 160 }}
                showsVerticalScrollIndicator={false}
              >
                {(lastOrder.items || []).map(({ item, qty, size }) => (
                  <View
                    key={size ? item.id + "-" + size : item.id}
                    style={{
                      flexDirection: "row",
                      justifyContent: "space-between",
                      marginBottom: 4,
                    }}
                  >
                    <Text style={cs.receiptItem} numberOfLines={1}>
                      {item.emoji} {item.name}
                      {size ? " [" + size + "]" : ""} ×{qty}
                    </Text>
                    <Text style={cs.receiptAmt}>
                      ₱{(item.price * qty).toFixed(2)}
                    </Text>
                  </View>
                ))}
              </ScrollView>
              <View
                style={{
                  height: 1,
                  backgroundColor: "rgba(1,31,75,0.15)",
                  marginVertical: 8,
                }}
              />
              <View
                style={{
                  flexDirection: "row",
                  justifyContent: "space-between",
                }}
              >
                <Text style={cs.receiptTotalLbl}>TOTAL</Text>
                <Text style={cs.receiptTotalVal}>
                  ₱{lastOrder.total.toFixed(2)}
                </Text>
              </View>
              <View
                style={{
                  flexDirection: "row",
                  justifyContent: "space-between",
                  marginTop: 3,
                }}
              >
                <Text style={cs.receiptSubLbl}>Payment</Text>
                <Text style={cs.receiptSubVal}>
                  {lastOrder.payment === "gcash"
                    ? "📱 GCash"
                    : lastOrder.payment === "credit"
                      ? "💳 Credit"
                      : "💵 Cash"}
                </Text>
              </View>
              {lastOrder.payment === "cash" && (
                <>
                  <View
                    style={{
                      flexDirection: "row",
                      justifyContent: "space-between",
                      marginTop: 3,
                    }}
                  >
                    <Text style={cs.receiptSubLbl}>💵 Cash</Text>
                    <Text style={cs.receiptSubVal}>
                      ₱{Number(lastOrder.amountPaid).toFixed(2)}
                    </Text>
                  </View>
                  <View
                    style={{
                      flexDirection: "row",
                      justifyContent: "space-between",
                      marginTop: 3,
                    }}
                  >
                    <Text style={cs.receiptSubLbl}>Change</Text>
                    <Text style={[cs.receiptSubVal, { color: "#27ae60" }]}>
                      ₱{Number(lastOrder.change).toFixed(2)}
                    </Text>
                  </View>
                </>
              )}
              {lastOrder.payment === "gcash" && (
                <>
                  <View
                    style={{
                      flexDirection: "row",
                      justifyContent: "space-between",
                      marginTop: 3,
                    }}
                  >
                    <Text style={cs.receiptSubLbl}>📱 GCash</Text>
                    <Text style={[cs.receiptSubVal, { color: "#27ae60" }]}>
                      ✓ Verified
                    </Text>
                  </View>
                  {lastOrder.gcashRef && (
                    <View
                      style={{
                        flexDirection: "row",
                        justifyContent: "space-between",
                        marginTop: 3,
                      }}
                    >
                      <Text style={cs.receiptSubLbl}>Ref #</Text>
                      <Text style={cs.receiptSubVal}>{lastOrder.gcashRef}</Text>
                    </View>
                  )}
                </>
              )}
              {lastOrder.payment === "credit" && (
                <>
                  <View
                    style={{
                      flexDirection: "row",
                      justifyContent: "space-between",
                      marginTop: 3,
                    }}
                  >
                    <Text style={cs.receiptSubLbl}>🪙 Credit</Text>
                    <Text style={[cs.receiptSubVal, { color: "#c9a84c" }]}>
                      Utang
                    </Text>
                  </View>
                  {lastOrder.memberName && (
                    <View
                      style={{
                        flexDirection: "row",
                        justifyContent: "space-between",
                        marginTop: 3,
                      }}
                    >
                      <Text style={cs.receiptSubLbl}>Member</Text>
                      <Text style={cs.receiptSubVal}>
                        {lastOrder.memberName}
                      </Text>
                    </View>
                  )}
                </>
              )}
              <Text
                style={{
                  fontFamily: "GoogleSans_700Bold",
                  fontSize: 12,
                  color: "#1a3a6b",
                  textAlign: "center",
                  marginTop: 12,
                }}
              >
                Thank you! 🙏
              </Text>
              <TouchableOpacity
                onPress={() => setReceiptVisible(false)}
                style={{
                  marginTop: 12,
                  paddingVertical: 10,
                  backgroundColor: "rgba(26,58,107,0.10)",
                  borderRadius: 10,
                  alignItems: "center",
                }}
              >
                <Text
                  style={{
                    fontFamily: "GoogleSans_700Bold",
                    fontSize: 13,
                    color: "#1a3a6b",
                  }}
                >
                  Close
                </Text>
              </TouchableOpacity>
            </View>
          </View>
        </Modal>
      )}

      {/* Size picker for apparel items */}
      <CashierSizePickerModal
        visible={!!sizePickerItem}
        item={sizePickerItem}
        onConfirm={(size) => {
          addToCart(sizePickerItem, size);
          setSizePickerItem(null);
        }}
        onClose={() => setSizePickerItem(null)}
      />
    </View>
  );
};

