// ─── ADMIN ITEM CARD (Manage Items tab) ──────────────────────────────────────
// Shows swipeable image carousel + item details. Tap card → admin actions.
const AdminItemCard = ({ item, imgs, onEdit, onDelete }) => {
  const [imgIdx, setImgIdx] = useState(0);
  const scrollRef = useRef(null);
  const CARD_IMG_W = 80;

  return (
    <View style={mm.foodCard}>
      <View
        style={[
          mm.foodCardInner,
          { backgroundColor: "rgba(225,238,248,0.85)" },
        ]}
      >
        {/* Admin action buttons */}
        <View style={mm.adminBtns}>
          <TouchableOpacity style={mm.editBtn} onPress={onEdit}>
            <MaterialIcons name="edit" size={11} color="#1a3a6b" />
          </TouchableOpacity>
          <TouchableOpacity style={mm.delBtn} onPress={onDelete}>
            <MaterialIcons name="delete" size={11} color="#e74c3c" />
          </TouchableOpacity>
        </View>

        {/* Image carousel or emoji */}
        {imgs.length > 0 ? (
          <View
            style={{
              width: CARD_IMG_W,
              height: CARD_IMG_W,
              borderRadius: 10,
              overflow: "hidden",
              alignSelf: "center",
              borderWidth: 1.5,
              borderColor: "rgba(255,255,255,0.85)",
            }}
          >
            <ScrollView
              ref={scrollRef}
              horizontal
              pagingEnabled
              showsHorizontalScrollIndicator={false}
              onMomentumScrollEnd={(e) =>
                setImgIdx(
                  Math.round(e.nativeEvent.contentOffset.x / CARD_IMG_W),
                )
              }
              style={{ width: CARD_IMG_W, height: CARD_IMG_W }}
              contentContainerStyle={{ width: CARD_IMG_W * imgs.length }}
            >
              {imgs.map((uri, i) => (
                <Image
                  key={i}
                  source={{ uri }}
                  style={{ width: CARD_IMG_W, height: CARD_IMG_W }}
                  resizeMode="cover"
                />
              ))}
            </ScrollView>
            {imgs.length > 1 && (
              <View
                style={{
                  position: "absolute",
                  bottom: 3,
                  left: 0,
                  right: 0,
                  flexDirection: "row",
                  justifyContent: "center",
                  gap: 3,
                }}
              >
                {imgs.map((_, i) => (
                  <TouchableOpacity
                    key={i}
                    onPress={() => {
                      scrollRef.current?.scrollTo({
                        x: i * CARD_IMG_W,
                        animated: true,
                      });
                      setImgIdx(i);
                    }}
                  >
                    <View
                      style={{
                        width: imgIdx === i ? 10 : 5,
                        height: 5,
                        borderRadius: 3,
                        backgroundColor:
                          imgIdx === i ? "#fff" : "rgba(255,255,255,0.50)",
                      }}
                    />
                  </TouchableOpacity>
                ))}
              </View>
            )}
          </View>
        ) : (
          <View style={mm.emojiCircle}>
            <Text style={mm.emojiTxt}>{item.emoji}</Text>
          </View>
        )}

        <Text style={mm.itemName} numberOfLines={2}>
          {item.name}
        </Text>
        <Text style={mm.itemStock}>Stock: {item.stock}</Text>
        <Text style={mm.itemPrice}>₱{item.price}.00</Text>
        {Array.isArray(item.colors) && item.colors.length > 0 && (
          <View
            style={{
              flexDirection: "row",
              flexWrap: "wrap",
              gap: 3,
              justifyContent: "center",
              marginTop: 2,
            }}
          >
            {(COLOR_OPTIONS[item.cat] || [])
              .filter((c) => item.colors.includes(c.label))
              .map((c) => (
                <View
                  key={c.label}
                  style={{
                    width: 10,
                    height: 10,
                    borderRadius: 5,
                    backgroundColor: c.hex,
                    borderWidth: 1,
                    borderColor: "rgba(0,0,0,0.15)",
                  }}
                />
              ))}
          </View>
        )}
        <TouchableOpacity style={mm.editItemBtn} onPress={onEdit}>
          <Text style={mm.editItemBtnTxt}>Edit Item</Text>
        </TouchableOpacity>
      </View>
    </View>
  );
};

// ─── MANAGE ITEMS SCREEN ──────────────────────────────────────────────────────
const ManageItemsScreen = ({
  items,
  categories,
  filtered,
  search,
  activeCategory,
  onSearch,
  onCategoryChange,
  onAddItem,
  onEditItem,
  onDeleteItem,
  isWide,
}) => {
  // FIX: 6 columns on wide, 3 on mobile
  const COLS = isWide ? 6 : 3;
  return (
    <View
      style={{
        flex: 1,
        minHeight: 0,
        flexDirection: isWide ? "row" : "column",
        overflow: "hidden",
      }}
    >
      {/* Categories — vertical sidebar on wide, horizontal strip on mobile */}
      {isWide ? (
        <View style={mm.catPanel}>
          <Text style={mm.catTitle}>CATEGORIES</Text>
          <WebScrollView style={{ flex: 1 }} contentContainerStyle={{ gap: 4 }}>
            {categories.map((cat) => (
              <TouchableOpacity
                key={cat}
                style={[mm.catBtn, activeCategory === cat && mm.catBtnActive]}
                onPress={() => onCategoryChange(cat)}
              >
                <Text
                  style={[
                    mm.catBtnTxt,
                    activeCategory === cat && mm.catBtnTxtActive,
                  ]}
                >
                  {cat}
                </Text>
              </TouchableOpacity>
            ))}
          </WebScrollView>
        </View>
      ) : (
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          style={{ flexGrow: 0, flexShrink: 0 }}
          contentContainerStyle={{
            paddingHorizontal: 8,
            paddingVertical: 6,
            gap: 5,
          }}
        >
          {categories.map((cat) => (
            <TouchableOpacity
              key={cat}
              style={[
                mm.catBtn,
                activeCategory === cat && mm.catBtnActive,
                { paddingVertical: 5, paddingHorizontal: 12 },
              ]}
              onPress={() => onCategoryChange(cat)}
            >
              <Text
                style={[
                  mm.catBtnTxt,
                  activeCategory === cat && mm.catBtnTxtActive,
                ]}
              >
                {cat}
              </Text>
            </TouchableOpacity>
          ))}
        </ScrollView>
      )}

      <View style={{ flex: 1, minHeight: 0, minWidth: 0, overflow: "hidden" }}>
        <View style={mm.headerRow}>
          <Text style={mm.headerLbl} numberOfLines={1}>
            {search.trim()
              ? 'RESULTS FOR "' + search.toUpperCase() + '"'
              : activeCategory === "All"
                ? "ALL ITEMS"
                : activeCategory.toUpperCase()}
          </Text>
          <View style={mm.searchBox}>
            <MaterialIcons name="search" size={13} color="rgba(1,31,75,0.40)" />
            <TextInput
              style={mm.searchInput}
              placeholder="Search..."
              placeholderTextColor="rgba(1,31,75,0.35)"
              value={search}
              onChangeText={onSearch}
            />
            {search.length > 0 && (
              <TouchableOpacity onPress={() => onSearch("")}>
                <Text
                  style={{
                    color: "rgba(1,31,75,0.45)",
                    fontWeight: "700",
                    fontSize: 12,
                  }}
                >
                  ✕
                </Text>
              </TouchableOpacity>
            )}
          </View>
          <TouchableOpacity style={mm.addBtn} onPress={onAddItem}>
            <MaterialIcons name="add" size={15} color="#fff" />
            <Text style={mm.addBtnTxt}>Add Item</Text>
          </TouchableOpacity>
        </View>
        <View
          style={{
            height: 1,
            backgroundColor: "rgba(1,31,75,0.10)",
            marginBottom: 8,
            marginHorizontal: 8,
          }}
        />
        <WebScrollView
          style={{ flex: 1 }}
          contentContainerStyle={{
            padding: 10,
            paddingHorizontal: 12,
            gap: 8,
            paddingBottom: 20,
          }}
        >
          {filtered.length === 0 ? (
            <Text style={mm.emptyTxt}>No items found.</Text>
          ) : (
            Array.from(
              { length: Math.ceil(filtered.length / COLS) },
              (_, rowIdx) => (
                <View
                  key={rowIdx}
                  style={{
                    flexDirection: "row",
                    gap: 8,
                    alignItems: "stretch",
                  }}
                >
                  {filtered
                    .slice(rowIdx * COLS, rowIdx * COLS + COLS)
                    .map((item) => {
                      const imgs =
                        Array.isArray(item.images) && item.images.length > 0
                          ? item.images
                          : item.image
                            ? [item.image]
                            : [];
                      return (
                        <View
                          key={item.id}
                          style={{ flex: 1, minWidth: 0, alignSelf: "stretch" }}
                        >
                          <AdminItemCard
                            item={item}
                            imgs={imgs}
                            onEdit={() => onEditItem(item)}
                            onDelete={() => onDeleteItem(item.id)}
                          />
                        </View>
                      );
                    })}
                  {Array.from({
                    length:
                      COLS -
                      filtered.slice(rowIdx * COLS, rowIdx * COLS + COLS)
                        .length,
                  }).map((_, i) => (
                    <View key={"e-" + i} style={{ flex: 1 }} />
                  ))}
                </View>
              ),
            )
          )}
        </WebScrollView>
      </View>
    </View>
  );
};

