// ─── INVENTORY SCREEN ─────────────────────────────────────────────────────────
const InventoryScreen = ({ items, maxQtyMap, onAddItem, onEditItem }) => {
  const today = new Date();

  // ── Date label formatting ─────────────────────────────────────────────────
  const formatDateLabel = (d) => {
    const now = new Date();
    const todayKey = now.toDateString();
    const yestKey = new Date(now - 86400000).toDateString();
    const opts = { month: "long", day: "numeric", year: "numeric" };
    if (d.toDateString() === todayKey)
      return "Today's Stocks, " + d.toLocaleDateString("en-PH", opts);
    if (d.toDateString() === yestKey)
      return "Yesterday's Stocks, " + d.toLocaleDateString("en-PH", opts);
    return "Stocks — " + d.toLocaleDateString("en-PH", opts);
  };

  // ── Calendar date picker state ─────────────────────────────────────────────
  const [selectedDate, setSelectedDate] = useState(today);
  const [showDatePicker, setShowDatePicker] = useState(false);

  // Build calendar grid for selected month
  const [calMonth, setCalMonth] = useState(today.getMonth());
  const [calYear, setCalYear] = useState(today.getFullYear());

  const calDays = (() => {
    const first = new Date(calYear, calMonth, 1).getDay();
    const days = new Date(calYear, calMonth + 1, 0).getDate();
    const cells = [];
    for (let i = 0; i < first; i++) cells.push(null);
    for (let d = 1; d <= days; d++) cells.push(d);
    return cells;
  })();

  const MONTHS = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
  ];
  const DAYS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

  // ── Unit of Measure per item (editable) ───────────────────────────────────
  const [units, setUnits] = useState({});
  const getUnit = (id) => units[id] || "pcs";
  const UNIT_OPTIONS = [
    "pcs",
    "kilo",
    "case",
    "pack",
    "box",
    "dozen",
    "liter",
    "bag",
  ];
  const [unitDropdown, setUnitDropdown] = useState(null);

  // ── Max QTY per item (editable) ────────────────────────────────────────────
  const getMax = (id) =>
    maxQtyMap && maxQtyMap[id] !== undefined
      ? maxQtyMap[id]
      : (items.find((i) => i.id === id) || {}).maxQty || 50;

  // ── Totals ────────────────────────────────────────────────────────────────
  const overallPrice = items.reduce((s, i) => s + i.price, 0);
  const overallQty = items.reduce((s, i) => s + i.stock, 0);
  const grandTotal = items.reduce((s, i) => s + i.price * i.stock, 0);

  return (
    <View
      style={{
        flex: 1,
        minHeight: 0,
        overflow: "hidden",
        position: "relative",
      }}
    >
      <View
        style={{
          flexDirection: "row",
          alignItems: "center",
          gap: 8,
          marginHorizontal: 14,
          marginTop: 8,
          marginBottom: 6,
        }}
      >
        <TouchableOpacity
          style={inv2.titleRow}
          onPress={() => setShowDatePicker((p) => !p)}
          activeOpacity={0.8}
        >
          <Text style={inv2.titleText}>{formatDateLabel(selectedDate)}</Text>
          <Text style={inv2.titleCaret}>{showDatePicker ? "▲" : "▼"}</Text>
        </TouchableOpacity>
        <TouchableOpacity
          style={inv2.addItemBtn}
          onPress={() => onAddItem && onAddItem()}
          activeOpacity={0.8}
        >
          <Text style={inv2.addItemBtnTxt}>+ Add Item</Text>
        </TouchableOpacity>
      </View>

      {/* ── Calendar dropdown ── */}
      {showDatePicker && (
        <View style={inv2.calCard}>
          {/* Month nav */}
          <View style={inv2.calNav}>
            <TouchableOpacity
              style={inv2.calNavBtn}
              onPress={() => {
                if (calMonth === 0) {
                  setCalMonth(11);
                  setCalYear((y) => y - 1);
                } else setCalMonth((m) => m - 1);
              }}
            >
              <Text style={inv2.calNavTxt}>‹</Text>
            </TouchableOpacity>
            <Text style={inv2.calMonthLbl}>
              {MONTHS[calMonth]} {calYear}
            </Text>
            <TouchableOpacity
              style={inv2.calNavBtn}
              onPress={() => {
                if (calMonth === 11) {
                  setCalMonth(0);
                  setCalYear((y) => y + 1);
                } else setCalMonth((m) => m + 1);
              }}
            >
              <Text style={inv2.calNavTxt}>›</Text>
            </TouchableOpacity>
          </View>
          {/* Day headers */}
          <View style={inv2.calDaysRow}>
            {DAYS.map((d) => (
              <Text key={d} style={inv2.calDayHdr}>
                {d}
              </Text>
            ))}
          </View>
          {/* Date grid */}
          <View style={inv2.calGrid}>
            {calDays.map((day, idx) => {
              if (!day) return <View key={"e" + idx} style={inv2.calCell} />;
              const thisDate = new Date(calYear, calMonth, day);
              const isSelected =
                thisDate.toDateString() === selectedDate.toDateString();
              const isToday = thisDate.toDateString() === today.toDateString();
              return (
                <TouchableOpacity
                  key={idx}
                  style={[
                    inv2.calCell,
                    isSelected && inv2.calCellSel,
                    isToday && !isSelected && inv2.calCellToday,
                  ]}
                  onPress={() => {
                    setSelectedDate(new Date(calYear, calMonth, day));
                    setShowDatePicker(false);
                  }}
                >
                  <Text
                    style={[inv2.calCellTxt, isSelected && inv2.calCellTxtSel]}
                  >
                    {day}
                  </Text>
                </TouchableOpacity>
              );
            })}
          </View>
        </View>
      )}

      {/* ── Table ── */}
      <View style={inv2.tableWrap}>
        {/* Header */}
        <View style={inv2.thead}>
          <Text style={[inv2.th, inv2.colName]}>ITEM NAME</Text>
          <Text style={[inv2.th, inv2.colCat]}>CATEGORY</Text>
          <Text style={[inv2.th, inv2.colQty]}>QTY</Text>
          <Text style={[inv2.th, inv2.colMaxQty]}>MAX QTY</Text>
          <Text style={[inv2.th, inv2.colPrice]}>PRICE</Text>
          <Text style={[inv2.th, inv2.colValue]}>VALUE</Text>
          <Text style={[inv2.th, inv2.colRestock]}>RE-STOCK</Text>
        </View>

        {/* Rows */}
        <WebScrollView style={{ flex: 1 }} contentContainerStyle={{ gap: 0 }}>
          {items.map((item, idx) => {
            const max = getMax(item.id);
            const restock = Math.max(0, max - item.stock);
            return (
              <TouchableOpacity
                key={item.id}
                style={[inv2.trow, idx % 2 === 0 && inv2.trowAlt]}
                onPress={() => onEditItem && onEditItem(item)}
                activeOpacity={0.75}
              >
                {/* Item Name */}
                <View style={[inv2.td, inv2.colName]}>
                  <Text style={inv2.tdName} numberOfLines={1}>
                    {item.emoji} {item.name}
                  </Text>
                </View>
                {/* Category */}
                <View style={[inv2.td, inv2.colCat]}>
                  <Text style={inv2.tdMuted} numberOfLines={1}>
                    {item.cat}
                  </Text>
                </View>
                {/* QTY */}
                <View style={[inv2.td, inv2.colQty]}>
                  <Text
                    style={[
                      inv2.tdNum,
                      item.stock === 0 && {
                        color: "#e74c3c",
                        fontFamily: "GoogleSans_700Bold",
                      },
                      item.stock <= 5 &&
                        item.stock > 0 && {
                          color: "#b85c00",
                          fontFamily: "GoogleSans_700Bold",
                        },
                    ]}
                  >
                    {item.stock}
                  </Text>
                </View>
                {/* Max QTY */}
                <View style={[inv2.td, inv2.colMaxQty]}>
                  <Text style={[inv2.tdNum, { textAlign: "center" }]}>
                    {getMax(item.id)}
                  </Text>
                </View>
                {/* Price */}
                <View style={[inv2.td, inv2.colPrice]}>
                  <Text style={inv2.tdNum}>₱{item.price.toLocaleString()}</Text>
                </View>
                {/* Value */}
                <View style={[inv2.td, inv2.colValue]}>
                  <Text
                    style={[
                      inv2.tdNum,
                      { color: "#1a3a6b", fontFamily: "GoogleSans_700Bold" },
                    ]}
                  >
                    ₱{(item.price * item.stock).toLocaleString()}
                  </Text>
                </View>
                {/* Re-Stock */}
                <View style={[inv2.td, inv2.colRestock]}>
                  {restock > 0 ? (
                    <View style={inv2.restockBadge}>
                      <Text style={inv2.restockNeed}>Need {restock}</Text>
                      <Text style={inv2.restockSub}>
                        ({item.stock}/{max})
                      </Text>
                    </View>
                  ) : (
                    <Text style={inv2.restockOk}>✓ OK</Text>
                  )}
                </View>
              </TouchableOpacity>
            );
          })}
        </WebScrollView>
        {/* Static TOTALS footer */}
        <View style={inv2.tfooter}>
          <View style={[inv2.td, inv2.colName]}>
            <Text style={inv2.tfootLbl}>TOTALS</Text>
          </View>
          <View style={[inv2.td, inv2.colCat]} />
          <View style={[inv2.td, inv2.colQty]}>
            <Text style={[inv2.tfootVal, { textAlign: "center" }]}>
              {overallQty}
            </Text>
          </View>
          <View style={[inv2.td, inv2.colMaxQty]} />
          <View style={[inv2.td, inv2.colPrice]}>
            <Text style={[inv2.tfootVal, { textAlign: "center" }]}>
              ₱{overallPrice.toLocaleString()}
            </Text>
          </View>
          <View style={[inv2.td, inv2.colValue]}>
            <Text
              style={[inv2.tfootVal, { color: "#8a6500", textAlign: "center" }]}
            >
              ₱{grandTotal.toLocaleString()}
            </Text>
          </View>
          <View style={[inv2.td, inv2.colRestock]} />
        </View>
      </View>
    </View>
  );
};

