// ─── SALES REPORT ───────────────────────────────

// ─── MERCHANDISE SALES PANEL ─────────────────────────────────────────────────
const MerchandiseSalesPanel = ({ orders, items }) => {
  const pulseAnim = useRef(new Animated.Value(1)).current;

  useEffect(() => {
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(pulseAnim, {
          toValue: 0.3,
          duration: 900,
          useNativeDriver: true,
        }),
        Animated.timing(pulseAnim, {
          toValue: 1,
          duration: 900,
          useNativeDriver: true,
        }),
      ]),
    );
    loop.start();
    return () => loop.stop();
  }, []);

  const today = new Date().toDateString();

  const todayOrders = orders.filter((o) => {
    try {
      if (o.createdAt) return new Date(o.createdAt).toDateString() === today;
      if (o.time) return new Date(o.time).toDateString() === today;
      return false;
    } catch {
      return false;
    }
  });

  const todaySales = todayOrders.reduce((s, o) => s + Number(o.total || 0), 0);
  const itemsSold = todayOrders.reduce(
    (s, o) => s + (o.items || []).reduce((a, i) => a + (i.qty || 1), 0),
    0,
  );
  const lowStockCount = (items || []).filter(
    (i) => i.stock > 0 && i.stock <= 5,
  ).length;
  const outOfStockCount = (items || []).filter((i) => i.stock === 0).length;

  const recentOrders = [...todayOrders].sort((a, b) => {
    const ta = b.createdAt || new Date(b.time || 0).getTime() || 0;
    const tb = a.createdAt || new Date(a.time || 0).getTime() || 0;
    return ta - tb;
  });

  const fmtTime = (o) => {
    try {
      const ts = o.createdAt || o.time;
      const d = new Date(ts);
      if (isNaN(d)) return "";
      let h = d.getHours();
      const m = String(d.getMinutes()).padStart(2, "0");
      const ampm = h >= 12 ? "PM" : "AM";
      h = h % 12 || 12;
      return `${h}:${m} ${ampm}`;
    } catch {
      return "";
    }
  };

  return (
    <View style={sp.root}>
      <View style={sp.titleRow}>
        <Animated.View style={[sp.liveDot, { opacity: pulseAnim }]} />
        <Text style={sp.title}>SALES OVERVIEW</Text>
      </View>

      {/* Stat cards row 1 */}
      <View style={sp.statRow}>
        <LinearGradient
          colors={["#27ae60", "#2ecc71"]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={sp.statCard}
        >
          <Text style={sp.statVal}>₱{todaySales.toFixed(0)}</Text>
          <Text style={sp.statLabel}>Today's Sales</Text>
        </LinearGradient>
        <LinearGradient
          colors={["#1a3a6b", "#2e5fa3"]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={sp.statCard}
        >
          <Text style={sp.statVal}>{itemsSold}</Text>
          <Text style={sp.statLabel}>Items Sold</Text>
        </LinearGradient>
      </View>

      {/* Stat cards row 2 */}
      <View style={sp.statRow}>
        <LinearGradient
          colors={["#e67e22", "#f39c12"]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={sp.statCard}
        >
          <Text style={sp.statVal}>{lowStockCount}</Text>
          <Text style={sp.statLabel}>Low Stock</Text>
        </LinearGradient>
        <LinearGradient
          colors={["#c0392b", "#e74c3c"]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={sp.statCard}
        >
          <Text style={sp.statVal}>{outOfStockCount}</Text>
          <Text style={sp.statLabel}>Out of Stock</Text>
        </LinearGradient>
      </View>

      <Text style={sp.recentLabel}>TODAY'S ORDERS</Text>

      {/* ── Compact table ── */}
      <View style={sp.tableWrap}>
        {/* Table header */}
        <View style={sp.tableHeader}>
          <Text style={[sp.tableHeadTxt, { flex: 1 }]}>Order</Text>
          <Text style={[sp.tableHeadTxt, { width: 48, textAlign: "center" }]}>
            Pay
          </Text>
          <Text style={[sp.tableHeadTxt, { width: 38, textAlign: "right" }]}>
            Time
          </Text>
          <Text style={[sp.tableHeadTxt, { width: 50, textAlign: "right" }]}>
            Total
          </Text>
        </View>

        <WebScrollView style={{ flex: 1, minHeight: 0 }}>
          {recentOrders.length === 0 ? (
            <View style={sp.emptyBox}>
              <Text style={sp.emptyIco}>🛍️</Text>
              <Text style={sp.emptyTxt}>No orders today</Text>
            </View>
          ) : (
            recentOrders.map((order, idx) => {
              const itemsList = (order.items || [])
                .map((i) => `${i.item?.name || i.name || "?"} x${i.qty || 1}`)
                .join(", ");
              const payLabel =
                order.payment === "gcash"
                  ? "GCash"
                  : order.payment === "credit"
                    ? "Credit"
                    : "Cash";
              const isLast = idx === recentOrders.length - 1;
              return (
                <View
                  key={order.id}
                  style={[
                    sp.tableRow,
                    {
                      borderBottomWidth: isLast ? 0 : 1,
                      backgroundColor:
                        idx % 2 === 0
                          ? "transparent"
                          : "rgba(255,255,255,0.35)",
                    },
                  ]}
                >
                  <View style={{ flex: 1, paddingRight: 6 }}>
                    <Text style={sp.orderId} numberOfLines={1}>
                      #{order.orderNo || order.id?.slice(-4) || "--"}
                    </Text>
                    <Text style={sp.orderItems} numberOfLines={1}>
                      {itemsList}
                    </Text>
                  </View>
                  <Text
                    style={{
                      width: 48,
                      textAlign: "center",
                      fontFamily: "GoogleSans_700Bold",
                      fontSize: 8,
                      color: "rgba(1,31,75,0.60)",
                    }}
                    numberOfLines={1}
                  >
                    {payLabel}
                  </Text>
                  <Text
                    style={[sp.orderTime, { width: 38, textAlign: "right" }]}
                    numberOfLines={1}
                  >
                    {fmtTime(order)}
                  </Text>
                  <Text
                    style={[sp.orderTotal, { width: 50, textAlign: "right" }]}
                  >
                    ₱{Number(order.total).toFixed(0)}
                  </Text>
                </View>
              );
            })
          )}
        </WebScrollView>
      </View>
    </View>
  );
};

const sp = StyleSheet.create({
  root: { flex: 1, padding: 10, minHeight: 0, overflow: "hidden" },
  titleRow: {
    flexDirection: "row",
    alignItems: "center",
    gap: 5,
    marginBottom: 8,
    justifyContent: "center",
  },
  liveDot: { width: 8, height: 8, borderRadius: 4, backgroundColor: "#27ae60" },
  title: {
    fontFamily: "GoogleSans_700Bold",
    fontSize: 10,
    color: "#1a2d4e",
    letterSpacing: 1.5,
    textDecorationLine: "underline",
    textAlign: "center",
  },
  statRow: { flexDirection: "row", gap: 6, marginBottom: 6 },
  statCard: {
    flex: 1,
    borderRadius: 10,
    paddingVertical: 10,
    paddingHorizontal: 8,
    alignItems: "center",
    gap: 2,
  },
  statVal: {
    fontFamily: "GoogleSans_700Bold",
    fontSize: 18,
    color: "#fff",
    lineHeight: 22,
  },
  statLabel: {
    fontFamily: "GoogleSans_700Bold",
    fontSize: 8,
    color: "rgba(255,255,255,0.85)",
    letterSpacing: 0.5,
    textAlign: "center",
  },
  recentLabel: {
    fontFamily: "GoogleSans_700Bold",
    fontSize: 9,
    color: "rgba(1,31,75,0.50)",
    letterSpacing: 1.2,
    marginBottom: 5,
    marginTop: 4,
  },
  emptyBox: { padding: 20, alignItems: "center", gap: 6 },
  emptyIco: { fontSize: 28 },
  emptyTxt: {
    fontFamily: "GoogleSans_400Regular",
    fontSize: 11,
    color: "rgba(1,31,75,0.35)",
    textAlign: "center",
  },
  // ── Compact table styles ──
  tableWrap: {
    flex: 1,
    minHeight: 0,
    backgroundColor: "rgba(255,255,255,0.55)",
    borderRadius: 12,
    borderWidth: 1,
    borderColor: "rgba(255,255,255,0.80)",
    overflow: "hidden",
  },
  tableHeader: {
    flexDirection: "row",
    alignItems: "center",
    backgroundColor: "rgba(26,58,107,0.10)",
    paddingHorizontal: 10,
    paddingVertical: 5,
    borderBottomWidth: 1,
    borderBottomColor: "rgba(26,58,107,0.12)",
  },
  tableHeadTxt: {
    fontFamily: "GoogleSans_700Bold",
    fontSize: 8,
    color: "rgba(1,31,75,0.50)",
    letterSpacing: 0.8,
    textTransform: "uppercase",
  },
  tableRow: {
    flexDirection: "row",
    alignItems: "center",
    paddingHorizontal: 10,
    paddingVertical: 6,
    borderBottomColor: "rgba(26,58,107,0.07)",
  },
  orderId: { fontFamily: "GoogleSans_700Bold", fontSize: 10, color: "#0d2540" },
  orderTime: {
    fontFamily: "GoogleSans_400Regular",
    fontSize: 9,
    color: "rgba(1,31,75,0.45)",
  },
  orderTotal: {
    fontFamily: "GoogleSans_700Bold",
    fontSize: 11,
    color: "#c9a84c",
  },
  orderItems: {
    fontFamily: "GoogleSans_400Regular",
    fontSize: 9,
    color: "rgba(1,31,75,0.55)",
    lineHeight: 12,
  },
});

// ─── MAIN SCREEN ──────────────────────────────────────────────────────────────
export default function ManageMerchandiseScreen({ navigation, route }) {
  const { width, height } = useWindowDimensions();
  const isSmall = width < 400;
  const isTablet = width >= 600 && width < 900;
  const isWide = width >= 900;

  // ── Use shared MerchandiseContext (same data as MerchandiseScreen visitor) ──
  const {
    items,
    ads,
    categories,
    orders,
    saveItem,
    deleteItem,
    saveAd,
    setAds,
    addOrder,
    updateOrderStatus,
    deductStock,
    reloadFromStorage,
  } = useMerchandise();

  // Firestore onSnapshot handles real-time sync — no polling needed
  useFocusEffect(
    useCallback(() => {
      reloadFromStorage();
    }, [reloadFromStorage]),
  );

  // ── Fonts ─────────────────────────────────────────────────────────────────
  const [fontsLoaded] = useFonts({
    NotoSerif_700Bold,
    GoogleSans_400Regular,
    GoogleSans_500Medium,
    GoogleSans_700Bold,
  });

  // ── UI state ──────────────────────────────────────────────────────────────
  const [activeTab, setActiveTab] = useState("cashier");
  const [activeCategory, setActiveCategory] = useState("All");
  const [search, setSearch] = useState("");
  const [editItem, setEditItem] = useState(null);
  const [editItemModal, setEditItemModal] = useState(false);
  const [editAd, setEditAd] = useState(null);
  const [editAdModal, setEditAdModal] = useState(false);
  const [adCurrent, setAdCurrent] = useState(0);
  const [invMaxQty, setInvMaxQty] = useState({});
  const [salesCollapsed, setSalesCollapsed] = useState(true);

  // ── New order notification — direct Firestore subscription ─────────────────
  // Uses its own onSnapshot so it ALWAYS gets real-time updates,
  // independent of the context's update cycle.
  const [notifBanner, setNotifBanner] = useState(null);
  const notifAnim = useRef(new Animated.Value(-100)).current;
  const prevOrderIdsRef = useRef(null); // null = first load (skip sound/banner)

  useEffect(() => {
    // Subscribe directly to merchandise_orders collection for real-time notification
    const q = collection(db, "merchandise_orders");
    const unsub = onSnapshot(q, (snapshot) => {
      const currentIds = new Set(snapshot.docs.map((d) => d.id));

      // First snapshot — just record existing IDs, don't notify
      if (prevOrderIdsRef.current === null) {
        prevOrderIdsRef.current = currentIds;
        return;
      }

      // Find brand-new orders from member or visitor screens
      // NOTE: merchandise orders are saved with status='done' (not 'pending')
      // so we just detect any new doc that is NOT from the cashier tab
      const newOrders = snapshot.docs.filter((d) => {
        const data = d.data();
        return !prevOrderIdsRef.current.has(d.id) && data.source !== "cashier";
      });

      if (newOrders.length > 0) {
        const latest = newOrders[0].data();
        playOrderSound();
        const sourceLabel =
          latest.source === "member"
            ? latest.memberName || "member"
            : latest.source === "visitor"
              ? "visitor"
              : latest.source || "customer";
        setNotifBanner({
          orderNo: latest.orderNo || newOrders[0].id,
          source: sourceLabel,
          total: latest.total || 0,
        });
        Animated.sequence([
          Animated.spring(notifAnim, {
            toValue: 0,
            tension: 80,
            friction: 10,
            useNativeDriver: true,
          }),
          Animated.delay(4500),
          Animated.timing(notifAnim, {
            toValue: -120,
            duration: 350,
            useNativeDriver: true,
          }),
        ]).start(() => setNotifBanner(null));
      }

      prevOrderIdsRef.current = currentIds;
    });

    return () => unsub();
  }, []);

  const hdrFade = useRef(new Animated.Value(0)).current;
  const hdrTrans = useRef(new Animated.Value(-16)).current;
  const bodyFade = useRef(new Animated.Value(0)).current;
  const adScrollRef = useRef(null);

  useEffect(() => {
    Animated.parallel([
      Animated.timing(hdrFade, {
        toValue: 1,
        duration: 500,
        useNativeDriver: true,
      }),
      Animated.timing(hdrTrans, {
        toValue: 0,
        duration: 500,
        useNativeDriver: true,
      }),
    ]).start();
    Animated.timing(bodyFade, {
      toValue: 1,
      duration: 500,
      delay: 150,
      useNativeDriver: true,
    }).start();
  }, []);

  const bannerW = isWide ? Math.min(width * 0.6, 700) : width - 16;

  useEffect(() => {
    if (!ads.length) return;
    const t = setInterval(() => {
      setAdCurrent((prev) => {
        const next = (prev + 1) % ads.length;
        adScrollRef.current &&
          adScrollRef.current.scrollTo({ x: next * bannerW, animated: true });
        return next;
      });
    }, 5000);
    return () => clearInterval(t);
  }, [ads.length, bannerW]);

  const handleSearch = (text) => {
    setSearch(text);
    if (!text.trim()) return;
    const cats = [
      ...new Set(
        items
          .filter((i) => i.name.toLowerCase().includes(text.toLowerCase()))
          .map((i) => i.cat),
      ),
    ];
    setActiveCategory(cats.length === 1 ? cats[0] : "All");
  };

  const filtered = items.filter((i) => {
    if (search.trim())
      return i.name.toLowerCase().includes(search.toLowerCase());
    return activeCategory === "All" || i.cat === activeCategory;
  });

  const openAddItem = () => {
    setEditItem(emptyItem());
    setEditItemModal(true);
  };
  const openEditItem = (item) => {
    setEditItem({
      ...item,
      price: String(item.price),
      stock: String(item.stock),
    });
    setEditItemModal(true);
  };
  const handleSaveItem = (updated) => {
    saveItem(updated);
    if (updated.maxQty !== undefined)
      setInvMaxQty((p) => ({ ...p, [updated.id]: updated.maxQty }));
    setEditItemModal(false);
  };
  const handleDeleteItem = (id) => {
    if (Platform.OS === "web") {
      if (window.confirm("Delete this item? This cannot be undone."))
        deleteItem(id);
    } else {
      Alert.alert("Delete Item", "Are you sure?", [
        { text: "Cancel", style: "cancel" },
        { text: "Delete", style: "destructive", onPress: () => deleteItem(id) },
      ]);
    }
  };

  const handleSaveAd = async (updated) => {
    const base = {
      title: updated.title || "",
      sub: updated.sub || "",
      emoji: updated.emoji || "📢",
      image: updated.image || null,
      imageUrl: updated.imageUrl || "",
      bg: updated.bg || ["#1a3a6b", "#2e5fa3"],
      titleFmt: updated.titleFmt || {
        bold: true,
        italic: false,
        underline: false,
        font: "GoogleSans_700Bold",
      },
      subFmt: updated.subFmt || {
        bold: false,
        italic: false,
        underline: false,
        font: "GoogleSans_400Regular",
      },
      url: updated.url || "",
      target: updated.target || "both",
    };
    if (updated.isNew) {
      await saveAd({ id: Date.now().toString(), ...base });
    } else {
      await saveAd({ id: updated.id, ...base });
    }
    setEditAdModal(false);
  };
  const handleDeleteAd = async (id) => {
    // Delete from Firestore — real-time listener will update both web and mobile
    try {
      await deleteDoc(doc(db, "merchandise_ads", id));
    } catch (e) {
      console.warn("handleDeleteAd error:", e);
    }
  };

  const pendingCount = items.filter((i) => i.stock <= 5).length; // low stock alert

  if (!fontsLoaded) return null;

  const renderContent = () => {
    if (activeTab === "cashier")
      return (
        <CashierScreen
          items={items}
          categories={categories}
          addOrder={addOrder}
          deductStock={deductStock}
          isWide={isWide}
        />
      );
    if (activeTab === "menu")
      return (
        <ManageItemsScreen
          items={items}
          categories={categories}
          filtered={filtered}
          search={search}
          activeCategory={activeCategory}
          onSearch={handleSearch}
          onCategoryChange={setActiveCategory}
          onAddItem={openAddItem}
          onEditItem={openEditItem}
          onDeleteItem={handleDeleteItem}
          isWide={isWide}
        />
      );
    if (activeTab === "inventory")
      return (
        <InventoryScreen
          items={items}
          maxQtyMap={invMaxQty}
          onAddItem={openAddItem}
          onEditItem={openEditItem}
        />
      );
    if (activeTab === "history")
      return (
        <OrderHistoryScreen
          orders={orders}
          onUpdateStatus={updateOrderStatus}
        />
      );
    if (activeTab === "credits") return <EmployeeCreditsScreen />;
    if (activeTab === "report")
      return <SalesReportScreen orders={orders} items={items} />;
    return null;
  };

  return (
    <View style={styles.root}>
      <StatusBar
        barStyle="light-content"
        translucent
        backgroundColor="transparent"
      />
      <View
        style={[StyleSheet.absoluteFillObject, { backgroundColor: "#98bad5" }]}
      />
      <LinearGradient
        colors={[
          "rgba(198,220,235,0.85)",
          "rgba(152,186,213,0.40)",
          "rgba(80,110,150,0.0)",
        ]}
        locations={[0, 0.45, 1]}
        start={{ x: 0.5, y: 0.1 }}
        end={{ x: 0.5, y: 1 }}
        style={StyleSheet.absoluteFillObject}
      />
      <LinearGradient
        colors={[
          "rgba(50,80,120,0.45)",
          "rgba(50,80,120,0.0)",
          "rgba(50,80,120,0.45)",
        ]}
        locations={[0, 0.5, 1]}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={StyleSheet.absoluteFillObject}
      />
      <LinearGradient
        colors={["rgba(50,80,120,0.0)", "rgba(60,90,130,0.35)"]}
        locations={[0.4, 1]}
        start={{ x: 0.5, y: 0 }}
        end={{ x: 0.5, y: 1 }}
        style={StyleSheet.absoluteFillObject}
      />

      {/* ── NEW ORDER NOTIFICATION BANNER ── */}
      {notifBanner && (
        <Animated.View
          style={{
            position: "absolute",
            top: Platform.OS === "web" ? 12 : 44,
            left: 16,
            right: 16,
            zIndex: 999,
            transform: [{ translateY: notifAnim }],
          }}
        >
          <LinearGradient
            colors={["#1a3a6b", "#2c5282"]}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 0 }}
            style={{
              borderRadius: 14,
              paddingHorizontal: 16,
              paddingVertical: 12,
              flexDirection: "row",
              alignItems: "center",
              gap: 12,
              shadowColor: "#000",
              shadowOpacity: 0.35,
              shadowRadius: 12,
              shadowOffset: { width: 0, height: 4 },
              elevation: 16,
              borderWidth: 1,
              borderColor: "rgba(201,168,76,0.40)",
            }}
          >
            <Text style={{ fontSize: 24 }}>🔔</Text>
            <View style={{ flex: 1 }}>
              <Text
                style={{
                  fontFamily: "GoogleSans_700Bold",
                  fontSize: 13,
                  color: "#fff",
                  letterSpacing: 0.3,
                }}
              >
                New Merchandise Order #{notifBanner.orderNo}
              </Text>
              <Text
                style={{
                  fontFamily: "GoogleSans_400Regular",
                  fontSize: 11,
                  color: "rgba(255,255,255,0.75)",
                  marginTop: 1,
                }}
              >
                From: {notifBanner.source} · ₱
                {Number(notifBanner.total).toFixed(2)}
              </Text>
            </View>
          </LinearGradient>
        </Animated.View>
      )}

      {/* HEADER */}
      <Animated.View
        style={{
          opacity: hdrFade,
          transform: [{ translateY: hdrTrans }],
          marginTop: Platform.OS === "web" ? 16 : isSmall ? 32 : 36,
          marginHorizontal: isSmall ? 8 : 10,
          zIndex: 30,
          flexShrink: 0,
        }}
      >
        <View
          style={[
            styles.header,
            { paddingHorizontal: 20, paddingVertical: 10 },
          ]}
        >
          <TouchableOpacity
            style={styles.backBtn}
            onPress={() => navigation && navigation.goBack()}
          >
            <Text style={styles.backIcon}>←</Text>
          </TouchableOpacity>
          <View style={styles.headerCenter}>
            <Text
              style={[styles.headerH1, { fontSize: isSmall ? 13 : 18 }]}
              numberOfLines={1}
              adjustsFontSizeToFit
            >
              <Text style={styles.headerGold}>CESLA </Text>Merchandise
              Management
            </Text>
            <View style={styles.visitorTag}>
              <Text style={styles.visitorTagText}>📦 ADMIN PANEL</Text>
            </View>
          </View>
          <TouchableOpacity style={[styles.iconBtn, { position: "relative" }]}>
            <MaterialIcons name="notifications" size={19} color="#fff" />
            {pendingCount > 0 && (
              <View style={[styles.notifBadge, { backgroundColor: "#e67e22" }]}>
                <Text style={styles.notifBadgeTxt}>{pendingCount}</Text>
              </View>
            )}
          </TouchableOpacity>
        </View>
      </Animated.View>

      {/* BODY */}
      <Animated.View style={[styles.body, { opacity: bodyFade, flex: 1 }]}>
        <View
          style={{
            flex: 1,
            flexDirection: isWide ? "row" : "column",
            minHeight: 0,
            overflow: "hidden",
          }}
        >
          {/* LEFT PANEL — Order Monitoring */}
          {isWide ? (
            <View style={styles.leftPanel}>
              <MerchandiseSalesPanel orders={orders} items={items} />
            </View>
          ) : (
            /* Mobile/Tablet: collapsible sales overview */
            <View
              style={[
                styles.leftPanelMobile,
                salesCollapsed && { height: 36 },
                isTablet && !salesCollapsed && { height: 170 },
              ]}
            >
              {/* Collapse toggle header */}
              <TouchableOpacity
                onPress={() => setSalesCollapsed((v) => !v)}
                style={{
                  flexDirection: "row",
                  alignItems: "center",
                  justifyContent: "space-between",
                  paddingHorizontal: 12,
                  paddingVertical: 6,
                  backgroundColor: "rgba(26,58,107,0.15)",
                  borderBottomWidth: salesCollapsed ? 0 : 1,
                  borderColor: "rgba(255,255,255,0.30)",
                }}
                activeOpacity={0.8}
              >
                <View
                  style={{ flexDirection: "row", alignItems: "center", gap: 6 }}
                >
                  <View
                    style={{
                      width: 6,
                      height: 6,
                      borderRadius: 3,
                      backgroundColor: "#27ae60",
                    }}
                  />
                  <Text
                    style={{
                      fontFamily: "GoogleSans_700Bold",
                      fontSize: 10,
                      color: "#1a2d4e",
                      letterSpacing: 1.2,
                    }}
                  >
                    SALES OVERVIEW
                  </Text>
                </View>
                <MaterialIcons
                  name={salesCollapsed ? "expand-more" : "expand-less"}
                  size={18}
                  color="rgba(26,58,107,0.60)"
                />
              </TouchableOpacity>
              {!salesCollapsed && (
                <View style={{ flex: 1, minHeight: 0, overflow: "hidden" }}>
                  <MerchandiseSalesPanel orders={orders} items={items} />
                </View>
              )}
            </View>
          )}

          {/* RIGHT PANEL */}
          <View style={isWide ? styles.rightPanel : styles.rightPanelMobile}>
            {/* Ad Banner */}
            <View style={[styles.adWrapper, !isWide && { borderRadius: 12 }]}>
              <ScrollView
                ref={adScrollRef}
                horizontal
                pagingEnabled
                showsHorizontalScrollIndicator={false}
                onMomentumScrollEnd={(e) =>
                  setAdCurrent(
                    Math.round(e.nativeEvent.contentOffset.x / bannerW),
                  )
                }
                style={{ width: "100%" }}
                contentContainerStyle={{ width: bannerW * (ads.length + 1) }}
              >
                {ads.map((ad) => {
                  const imgSrc = ad.image
                    ? { uri: ad.image }
                    : ad.imageUrl
                      ? { uri: ad.imageUrl }
                      : null;
                  const titleStyle = {
                    fontFamily: ad.titleFmt?.font || "GoogleSans_700Bold",
                    fontStyle: ad.titleFmt?.italic ? "italic" : "normal",
                    fontWeight: ad.titleFmt?.bold ? "700" : "400",
                    textDecorationLine: ad.titleFmt?.underline
                      ? "underline"
                      : "none",
                  };
                  const subStyle = {
                    fontFamily: ad.subFmt?.font || "GoogleSans_400Regular",
                    fontStyle: ad.subFmt?.italic ? "italic" : "normal",
                    fontWeight: ad.subFmt?.bold ? "700" : "400",
                    textDecorationLine: ad.subFmt?.underline
                      ? "underline"
                      : "none",
                  };
                  const handleAdPress = () => {
                    if (ad.url) {
                      if (Platform.OS === "web") {
                        window.open(ad.url, "_blank");
                      } else {
                        import("react-native").then(({ Linking }) =>
                          Linking.openURL(ad.url),
                        );
                      }
                    }
                  };
                  return (
                    <LinearGradient
                      key={ad.id}
                      colors={ad.bg || ["#1a3a6b", "#2e5fa3"]}
                      start={{ x: 0, y: 0 }}
                      end={{ x: 1, y: 1 }}
                      style={[styles.adSlide, { width: bannerW }]}
                    >
                      {imgSrc ? (
                        <Image
                          source={imgSrc}
                          style={styles.adBgImg}
                          resizeMode="cover"
                        />
                      ) : (
                        <Text
                          style={[styles.adEmoji, isSmall && { fontSize: 28 }]}
                        >
                          {ad.emoji}
                        </Text>
                      )}
                      <TouchableOpacity
                        style={{ flex: 1, minWidth: 0 }}
                        onPress={handleAdPress}
                        activeOpacity={ad.url ? 0.8 : 1}
                      >
                        <Text
                          style={[
                            styles.adTitle,
                            isSmall && { fontSize: 13 },
                            titleStyle,
                          ]}
                          numberOfLines={1}
                        >
                          {ad.title}
                        </Text>
                        <Text
                          style={[
                            styles.adSub,
                            isSmall && { fontSize: 10 },
                            subStyle,
                          ]}
                          numberOfLines={1}
                        >
                          {ad.sub}
                        </Text>
                        {ad.url ? (
                          <Text
                            style={{
                              fontFamily: "GoogleSans_400Regular",
                              fontSize: 9,
                              color: "rgba(255,255,255,0.70)",
                              marginTop: 2,
                            }}
                          >
                            🔗 Tap to open link
                          </Text>
                        ) : null}
                      </TouchableOpacity>
                      <View style={styles.adBadge}>
                        <Text style={styles.adBadgeTxt}>AD</Text>
                      </View>
                      {ad.target && ad.target !== "both" && (
                        <View
                          style={[
                            styles.adBadge,
                            {
                              right: 38,
                              backgroundColor:
                                ad.target === "member"
                                  ? "rgba(39,174,96,0.55)"
                                  : "rgba(230,126,34,0.55)",
                            },
                          ]}
                        >
                          <Text style={styles.adBadgeTxt}>
                            {ad.target === "member" ? "MEMBER" : "VISITOR"}
                          </Text>
                        </View>
                      )}
                      <TouchableOpacity
                        style={styles.adEditBtn}
                        onPress={() => {
                          setEditAd({ ...ad });
                          setEditAdModal(true);
                        }}
                      >
                        <MaterialIcons name="edit" size={12} color="#fff" />
                      </TouchableOpacity>
                      <View style={styles.adDotsInner}>
                        {ads.map((_, i) => (
                          <TouchableOpacity
                            key={i}
                            onPress={() => {
                              adScrollRef.current &&
                                adScrollRef.current.scrollTo({
                                  x: i * bannerW,
                                  animated: true,
                                });
                              setAdCurrent(i);
                            }}
                          >
                            <View
                              style={[
                                styles.adDot,
                                adCurrent === i && styles.adDotActive,
                              ]}
                            />
                          </TouchableOpacity>
                        ))}
                      </View>
                    </LinearGradient>
                  );
                })}
                {/* Add new ad slide */}
                <TouchableOpacity
                  style={[
                    styles.adSlide,
                    {
                      width: bannerW,
                      backgroundColor: "rgba(26,58,107,0.18)",
                      justifyContent: "center",
                      alignItems: "center",
                      gap: 8,
                      borderWidth: 2,
                      borderColor: "rgba(255,255,255,0.40)",
                      borderStyle: "dashed",
                    },
                  ]}
                  onPress={() => {
                    setEditAd({
                      isNew: true,
                      id: Date.now().toString(),
                      title: "",
                      sub: "",
                      image: null,
                      imageUrl: "",
                      emoji: "📢",
                      bg: ["#1a3a6b", "#2e5fa3"],
                    });
                    setEditAdModal(true);
                  }}
                >
                  <MaterialIcons
                    name="add-circle-outline"
                    size={28}
                    color="rgba(26,58,107,0.55)"
                  />
                  <Text
                    style={{
                      fontFamily: "GoogleSans_700Bold",
                      fontSize: 12,
                      color: "rgba(26,58,107,0.55)",
                    }}
                  >
                    Add New Ad
                  </Text>
                </TouchableOpacity>
              </ScrollView>
            </View>

            {/* Tabs */}
            <View style={[styles.tabBar, isSmall && { paddingHorizontal: 2 }]}>
              <ScrollView
                horizontal
                showsHorizontalScrollIndicator={false}
                contentContainerStyle={{ gap: 2 }}
                style={{ flexGrow: 0 }}
              >
                {TABS.map((tab) => (
                  <TouchableOpacity
                    key={tab.key}
                    style={[
                      styles.tabBtn,
                      activeTab === tab.key && styles.tabBtnActive,
                      isSmall && { paddingHorizontal: 8, paddingVertical: 7 },
                    ]}
                    onPress={() => setActiveTab(tab.key)}
                    activeOpacity={0.8}
                  >
                    <MaterialIcons
                      name={tab.icon}
                      size={isSmall ? 12 : 13}
                      color={
                        activeTab === tab.key
                          ? "#1a3a6b"
                          : "rgba(255,255,255,0.80)"
                      }
                    />
                    <Text
                      style={[
                        styles.tabBtnTxt,
                        activeTab === tab.key && styles.tabBtnTxtActive,
                        isSmall && { fontSize: 9 },
                      ]}
                    >
                      {tab.label}
                    </Text>
                  </TouchableOpacity>
                ))}
              </ScrollView>
            </View>

            {/* Content area */}
            <View style={styles.contentArea}>{renderContent()}</View>
          </View>
        </View>
      </Animated.View>

      <ItemEditModal
        visible={editItemModal}
        item={editItem}
        categories={categories}
        onSave={handleSaveItem}
        onClose={() => setEditItemModal(false)}
      />
      <AdEditModal
        visible={editAdModal}
        ad={editAd}
        onSave={handleSaveAd}
        onClose={() => setEditAdModal(false)}
        onDelete={handleDeleteAd}
      />
    </View>
  );
}

